<script setup>import {money} from '../api/client.js';defineProps({trip:{type:Object,required:true}});defineEmits(['choose']);const clock=value=>new Date(value).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'});</script>
<template><article class="figma-trip-card"><div class="operator"><span class="bus-thumb">🚌</span><div><b>{{trip.vehicle.name}}</b><span>★ 4.5</span><small>{{trip.availableSeats}} ghế trống</small></div></div><div class="trip-time"><b>{{clock(trip.departureTime)}}</b><small>{{trip.origin.name}}</small></div><div class="trip-duration"><small>6h 30m</small><i></i><span>Đi thẳng</span></div><div class="trip-time"><b>{{clock(trip.arrivalTime)}}</b><small>{{trip.destination.name}}</small></div><div class="trip-fare"><strong>{{money(trip.price)}}</strong><small>{{trip.vehicle.type}} · {{trip.vehicle.floors || 1}} tầng</small><button class="btn primary" @click="$emit('choose',trip.id)">Chọn ghế</button></div></article></template>
